// pubspec.yaml: mobile_scanner + Dio
Future<AuthResult> authenticate(String scannedValue) async {
  // 1. Parse Digital Link URL or GS1 element string.
  final gs1 = parseGs1(scannedValue);   // returns {01: gtin, 21: serial, 17: expiry, ...}
  if (gs1 == null) return AuthResult.invalid(reason: 'Malformed code');

  // 2. Local sanity checks.
  if (!isValidGtin(gs1['01']!)) return AuthResult.invalid(reason: 'Bad GTIN');
  if (_expiryPassed(gs1['17'])) return AuthResult.invalid(reason: 'Expired');

  // 3. Backend call — brand-owner authentication service.
  try {
    final resp = await dio.get('/authenticate',
      queryParameters: {'gtin': gs1['01'], 'serial': gs1['21'], 'batch': gs1['10']});
    if (resp.data['status'] == 'authentic') {
      // 4. Optional: verify HMAC signature on the URL
      if (!_verifyHmac(scannedValue, resp.data['signature'])) {
        return AuthResult.suspicious(reason: 'Signature mismatch');
      }
      // 5. Log the scan (analytics + tamper detection)
      unawaited(_logScan(gs1, location: await currentLocation()));
      return AuthResult.authentic(product: resp.data['product']);
    }
    if (resp.data['status'] == 'already_scanned') {
      return AuthResult.suspicious(reason: 'Serial already redeemed');
    }
    return AuthResult.counterfeit(reason: resp.data['reason']);
  } catch (_) {
    return AuthResult.unknown(reason: 'Cannot verify (offline?)');
  }
}
